window.HOEREN_TESTS[97] = {"id":"im-wellnesshotel","name":"Im Wellnesshotel","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Gäste: Willkommen in unserem Wellnesshotel. Der große Pool ist heute leider geschlossen, wir reinigen ihn. Aber die Sauna und das kleine Becken sind normal geöffnet. Die Sauna ist also nicht zu, nur der große Pool. Ab morgen können Sie wieder im großen Pool schwimmen. Wir entschuldigen uns und wünschen einen erholsamen Tag!","gender":"f","q":"Was ist heute geschlossen?","opts":["Der große Pool.","Die Sauna.","Das kleine Becken."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Also, ich war so gestresst, dass meine Frau mir ein Wochenende im Wellnesshotel geschenkt hat. Massage, Sauna, einfach mal abschalten. Es war herrlich! Du arbeitest doch auch viel zu viel. Gönn dir auch mal so etwas. Ich gebe dir die Adresse. Ruf zurück, bis bald!","gender":"m","q":"Warum war Markus im Wellnesshotel?","opts":["Zum Abschalten und Entspannen.","Für eine Geschäftsreise.","Für einen Sportkurs."],"correct":0},{"transcript":"Achtung Gäste: Bitte beachten Sie die Regeln in der Sauna. In der Sauna sitzt man ohne Kleidung, aber immer auf einem Handtuch. Bitte seien Sie leise, die Sauna ist ein Ort der Ruhe. Nach dem Saunagang sollten Sie sich kalt abduschen. Genießen Sie Ihren Aufenthalt bei uns!","gender":"m","q":"Worauf soll man in der Sauna sitzen?","opts":["Auf einem Kissen.","Direkt auf dem Holz.","Auf einem Handtuch."],"correct":2},{"transcript":"Hi Lisa, hier ist Anna. Ich habe im Wellnesshotel eine tolle Massage bekommen. Die Therapeutin hat genau die verspannten Stellen gefunden. Danach war ich wie neu! Es gibt auch Gesichtsbehandlungen und ein Dampfbad. Wir sollten zusammen mal ein Wellness-Wochenende machen. Was meinst du? Melde dich!","gender":"f","q":"Was hat Anna besonders gut gefallen?","opts":["Das Essen.","Die Massage.","Der Pool."],"correct":1},{"transcript":"Liebe Gäste: Unser Wellnessbereich ist von 7 bis 22 Uhr geöffnet. Die letzten Behandlungen wie Massagen beginnen aber spätestens um 20 Uhr, nicht um 22 Uhr und nicht schon um 18 Uhr. Bitte buchen Sie Massagen früh, sie sind schnell ausgebucht. Bademäntel und Handtücher finden Sie auf Ihrem Zimmer. Wir wünschen viel Entspannung!","gender":"f","q":"Bis wann beginnen die letzten Massagen?","opts":["Bis 22 Uhr.","Bis 20 Uhr.","Bis 18 Uhr."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Was steht an welchem Tag auf dem Programm? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Im Hotel liegt das Programm für die Woche. Hast du es schon gesehen?"},{"speaker":"Lisa","gender":"f","text":"Ich schaue es gerade an. Wir wollen nicht jeden Tag nur im Zimmer liegen."},{"speaker":"Lukas","gender":"m","text":"Ich gehe am Montag in die Sauna. Abends ist sie frei und richtig heiß."},{"speaker":"Lisa","gender":"f","text":"Dann gehe ich nicht mit. Geht jemand in den Fitnessraum?"},{"speaker":"Lukas","gender":"m","text":"In den Fitnessraum geht diese Woche keiner. Alle wollen Ruhe."},{"speaker":"Lisa","gender":"f","text":"Ich bekomme am Dienstag eine Massage für den Rücken."},{"speaker":"Lukas","gender":"m","text":"Die dauert eine Stunde. Tom will am Mittwoch im Pool schwimmen."},{"speaker":"Lisa","gender":"f","text":"Er schwimmt lange vor dem Frühstück. Das mag er sehr."},{"speaker":"Lukas","gender":"m","text":"Er ist oft schon früh wach. Will jemand eine Maniküre?"},{"speaker":"Lisa","gender":"f","text":"Eine Maniküre wollen wir auch nicht."},{"speaker":"Lukas","gender":"m","text":"Sara bekommt am Donnerstag eine Gesichtsbehandlung."},{"speaker":"Lisa","gender":"f","text":"Danach soll die Haut weich und frisch sein. Das tut ihr gut."},{"speaker":"Lukas","gender":"m","text":"Das Zimmer ist oben und der Garten bleibt noch frei."},{"speaker":"Lisa","gender":"f","text":"Am Freitag macht Tim Yoga. Er sucht sich dazu eine ruhige Ecke."},{"speaker":"Lukas","gender":"m","text":"Dann lege ich das Programm auf den Tisch."},{"speaker":"Lisa","gender":"f","text":"Dann freue ich mich auf die ganze Woche."}],"options":[{"letter":"a","text":"Massage"},{"letter":"b","text":"Fitnessraum"},{"letter":"c","text":"Maniküre"},{"letter":"d","text":"Spazieren am See"},{"letter":"e","text":"Yoga"},{"letter":"f","text":"Gesichtsbehandlung"},{"letter":"g","text":"Sauna"},{"letter":"h","text":"Dampfbad"},{"letter":"i","text":"Im Pool schwimmen"}],"items":[{"person":"Montag","correct":"g"},{"person":"Dienstag","correct":"a"},{"person":"Mittwoch","correct":"i"},{"person":"Donnerstag","correct":"f"},{"person":"Freitag","correct":"e"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Gast","gender":"m","text":"Was kostet eine Massage? 40 Euro, 70 oder 100?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Die halbe Stunde 40 Euro. 100 Euro wäre eine Extra-Behandlung mit Öl. Sehr entspannend."},{"speaker":"Gast","gender":"m","text":"Und eine ganze Stunde? 70 oder 100?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Eine ganze Stunde 70 Euro. Nicht 40 und nicht 100, eine Stunde kostet 70. Ein guter Preis."},{"speaker":"Gast","gender":"m","text":"Dann eine ganze Stunde für 70 Euro. Danke schön!"}],"q":"Was kostet eine ganze Stunde Massage?","opts":["40 Euro.","70 Euro.","100 Euro."],"correct":1},{"lines":[{"speaker":"Gästin","gender":"f","text":"Wann beginnt der Yoga-Kurs? Um 8 Uhr, um 10 Uhr oder am Nachmittag?"},{"speaker":"Mitarbeiter","gender":"m","text":"Morgens um 8 Uhr am See. Um 10 Uhr ist Frühstücksschluss, am Nachmittag gibt es keinen Kurs."},{"speaker":"Gästin","gender":"f","text":"Muss ich mich anmelden? Also wirklich um 8, nicht um 10?"},{"speaker":"Mitarbeiter","gender":"m","text":"Nein, kommen Sie einfach hin. Der Kurs beginnt um 8 Uhr, nicht um 10 und nicht am Nachmittag."},{"speaker":"Gästin","gender":"f","text":"Super, dann um 8 Uhr am See. Danke."}],"q":"Wann beginnt der Yoga-Kurs?","opts":["Um 8 Uhr.","Um 10 Uhr.","Am Nachmittag."],"correct":0},{"lines":[{"speaker":"Gast","gender":"m","text":"Gibt es Bademäntel? Auf dem Zimmer, an der Rezeption oder an der Sauna?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Ja, auf Ihrem Zimmer. An der Rezeption liegen keine extra Bademäntel."},{"speaker":"Gast","gender":"m","text":"Und Handtücher für die Sauna? Auch auf dem Zimmer?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Die bekommen Sie am Eingang zur Sauna. Nicht auf dem Zimmer und nicht an der Rezeption, an der Sauna."},{"speaker":"Gast","gender":"m","text":"Verstanden, Bademantel auf dem Zimmer, Handtuch an der Sauna. Danke."}],"q":"Wo gibt es Handtücher für die Sauna?","opts":["Auf dem Zimmer.","Am Eingang zur Sauna.","An der Rezeption."],"correct":1},{"lines":[{"speaker":"Gästin","gender":"f","text":"Ist das Frühstück im Preis dabei? Bis 9 Uhr, bis 10 Uhr 30 oder bis 12 Uhr?"},{"speaker":"Mitarbeiter","gender":"m","text":"Ja, ein großes Buffet. Bis 9 Uhr wäre früh, bis 12 Uhr gibt es schon Mittagessen."},{"speaker":"Gästin","gender":"f","text":"Bis wann gibt es das? 10 Uhr 30, oder schon 9?"},{"speaker":"Mitarbeiter","gender":"m","text":"Bis 10 Uhr 30. Nicht bis 9 Uhr und nicht bis 12 Uhr, bis halb elf."},{"speaker":"Gästin","gender":"f","text":"Prima, dann bis 10 Uhr 30. Danke."}],"q":"Bis wann gibt es Frühstück?","opts":["Bis 9 Uhr.","Bis 12 Uhr.","Bis 10 Uhr 30."],"correct":2},{"lines":[{"speaker":"Gast","gender":"m","text":"Darf man Kinder mit in die Sauna nehmen? Ab 12, ab 16 oder jedes Alter?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Erst ab 16 Jahren, aus Gesundheitsgründen. Ab 12 und jedes Alter gelten hier nicht."},{"speaker":"Gast","gender":"m","text":"Und in den Pool? Auch ab 16, oder jedes Alter?"},{"speaker":"Mitarbeiterin","gender":"f","text":"In den Pool dürfen Kinder, ja. In die Sauna erst ab 16, nicht ab 12 und nicht jedes Alter."},{"speaker":"Gast","gender":"m","text":"Gut, Pool ja, Sauna ab 16. Danke."}],"q":"Ab welchem Alter darf man in die Sauna?","opts":["Ab 12 Jahren.","Jedes Alter.","Ab 16 Jahren."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Adler, der Leiterin eines Wellnesshotels. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Adler, warum kommen die Menschen ins Wellnesshotel?"},{"speaker":"Adler","gender":"f","text":"Vor allem, um sich zu erholen. Viele arbeiten zu viel und sind müde. Die meisten Gäste kommen, um sich zu erholen, das ist der Hauptgrund."},{"speaker":"Reporter","gender":"m","text":"Sind solche Hotels immer sehr teuer, oder gibt es Angebote?"},{"speaker":"Adler","gender":"f","text":"Nicht alle. Unter der Woche gibt es oft günstige Angebote. Wellnesshotels sind also nicht immer sehr teuer, man muss nur den Tag wählen."},{"speaker":"Reporter","gender":"m","text":"Was ist bei den Gästen am beliebtesten, Massagen oder Sauna?"},{"speaker":"Adler","gender":"f","text":"Die Massagen. Danach kommen Sauna und Pool. Auch Yoga mögen viele. Massagen sind bei den Gästen am beliebtesten, das buchen fast alle."},{"speaker":"Reporter","gender":"m","text":"Kommen auch Firmen zu Ihnen, mit ihren Mitarbeitern?"},{"speaker":"Adler","gender":"f","text":"Ja, immer mehr. Sie schicken ihre Mitarbeiter zur Erholung. Immer mehr Firmen machen das, nach stressigen Monaten."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie gestressten Menschen? Geht Erholung nur im teuren Hotel?"},{"speaker":"Adler","gender":"f","text":"Nehmen Sie sich auch zu Hause Zeit für sich. Ein Bad oder ein Spaziergang hilft schon. Erholung gibt es nicht nur im teuren Hotel, das kann jeder machen."}],"items":[{"q":"Frau Adler sagt, Wellnesshotels sind immer sehr teuer.","correct":"nein"},{"q":"Die meisten Gäste kommen, um sich zu erholen.","correct":"ja"},{"q":"Massagen sind bei den Gästen am beliebtesten.","correct":"ja"},{"q":"Sie meint, Erholung gibt es nur im teuren Hotel.","correct":"nein"},{"q":"Immer mehr Firmen schicken ihre Mitarbeiter zur Erholung.","correct":"ja"}]}]};
